func (c *Checker) tryCreateTypeReference(target *Type, typeArguments []*Type) *Type {
	if len(typeArguments) != 0 && target == c.emptyGenericType {
		return c.unknownType
	}
	return c.createTypeReference(target, typeArguments)
}

